CREATE OR REPLACE PROCEDURE DB1.S1.P5()
RETURNS VARCHAR
LANGUAGE SQL
AS
$$
DECLARE
    R1 RESULTSET DEFAULT (SELECT "Col_A", "Col_B" FROM DB1.S1.STRM1);
    N1 NUMBER DEFAULT 0;
BEGIN
    FOR REC IN R1 DO
        N1 := N1 + 1;
    END FOR;
    IF (N1 = 0) THEN
        RETURN 'empty';
    END IF;
    RETURN 'rows: ' || N1;
END;
$$;
